mapper.select:
SELECT MAX(cc.contract_id) AS contractId, MAX(pp.PROJECT_NUMBER) AS orderNo, LISTAGG(ccc.TIMES, ',') WITHIN GROUP (ORDER BY ccc.CONTRACT_ID) AS termNos, TO_CHAR(SYSDATE,'yyyy-mm-dd') AS trialTime, (NVL(SUM(ccc.PRINCIPAL), 0)+NVL(MIN(ccc.OUTSTANDING_PRINCIPAL), 0))*100 AS principal, NVL(SUM(ccc.INTEREST), 0)*100 AS interest, 0 AS penalty, 0 AS otherFee, (NVL(SUM(ccc.DUE_AMOUNT), 0)+NVL(MIN(ccc.OUTSTANDING_PRINCIPAL), 0))*100 AS payableAmount FROM CON_CONTRACT_CASHFLOW ccc INNER JOIN CON_CONTRACT cc ON ccc.CONTRACT_ID = cc.CONTRACT_ID INNER JOIN PRJ_PROJECT pp ON cc.project_id = pp.project_id INNER JOIN hls_bp_master hbm on pp.MANUFACTURER_ID = hbm.bp_id WHERE cc.contract_status = 'INCEPT' AND ccc.write_off_flag not in ('FULL') AND ccc.cf_direction='INFLOW' AND ccc.times not in (0) and nvl(ccc.plan_type,'NO') not in ('COMP','REPO') AND ccc.cf_item = 1 AND ccc.due_amount-nvl(ccc.RECEIVED_AMOUNT,0)>0 AND trunc(sysdate) - nvl(pp.buy_back_day,85) > trunc(ccc.DUE_DATE) AND hbm.bp_code in ('BP202408090380','BP202407230057')
AND ccc.CONTRACT_ID = #{contractId}
GROUP BY cc.CONTRACT_ID

SELECT l.notice_id, l.source_id, l.source_type, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code= 'YL.LEASING_NOTICE_TYPE' and scvb.value = l.source_type) source_type_n, CASE SCENE WHEN 'PRE_RISK THEN' THEN '人工审核' WHEN 'LOAN_AUDIT' THEN '放款审核' WHEN 'MORTGAGE_MATERIAL_AUDIT' THEN '抵押材料审核' END scene_n, l.scene, l.notice_status, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code= 'LN.NOTICE_STATUS' and scvb.value = l.notice_status) notice_status_n, l.error_message, l.description, l.resend_flag, (select scvb.MEANING from sys_code_value_b scvb, sys_code_b scb where scvb.CODE_ID = scb.CODE_ID and scb.code= 'LN.RESEND_FLAG' and scvb.value = l.resend_flag) resend_flags_n, dbms_lob.substr( notice_body ) AS notice_body, l.CREATION_DATE FROM LEASING_NOTICE l
and l.source_id=#{sourceId}
and l.source_type=#{sourceType}
and l.scene=#{scene}
and l.notice_status=#{noticeStatus}
and l.resend_flag=#{resendFlag}
order by l.CREATION_DATE desc

select hbm.BP_CODE,hbm.bp_id from prj_project pp,hls_bp_master hbm
where pp.MANUFACTURER_ID = hbm.bp_id
and pp.project_id = #{projectId}
